solution:
def rollout(policy,steps=8):
    threat=0;hp=5;history=[]
    for _ in range(steps):
        action=policy(threat,hp)
        if action=='wait': threat+=1
        elif action=='defend': threat=max(0,threat-2)
        else: raise ValueError('Unknown action')
        if threat>=3: hp=max(0,hp-1)
        history.append((threat,hp))
        if hp==0: break
    return history

