solution:
def standardised_rate(reference_mix,conditional_rates):
    if set(reference_mix)!=set(conditional_rates) or abs(sum(reference_mix.values())-1)>1e-9:
        raise ValueError('Need matching classes and a normalised mix')
    if not all(0<=v<=1 for v in list(reference_mix.values())+list(conditional_rates.values())):
        raise ValueError('Shares and rates must be probabilities')
    return sum(reference_mix[g]*conditional_rates[g] for g in reference_mix)

