solution:
def paired_gain(baseline,candidate):
    if not baseline or set(baseline)!=set(candidate):
        raise ValueError('Need complete nonempty pairs')
    if not all(v in (0,1) for v in list(baseline.values())+list(candidate.values())):
        raise ValueError('Need known binary outcomes')
    return sum(candidate[k]-baseline[k] for k in baseline)/len(baseline)
